mapper.update:
UPDATE icam10_fee
   SET icam10_fee = #{fee}
 WHERE icam10_fee_id = #{feeId}
   AND icam10_company_id = #{companyId}

mapper.select:
SELECT sys12_day
  FROM sys12_calendar
 WHERE sys12_company_id = #{companyId}
   AND sys12_day BETWEEN #{startDate} AND #{closeDate}
 ORDER BY sys12_day
